healthFile.addEventListener('change',async()=>{const file=healthFile.files?.[0];if(!file||healthImportBusy)return;healthImportBusy=true;healthStatus.textContent=`Lecture de ${file.name}…`;try{const parsed=await parseHealthFile(file);const useful=['steps','stepGoal','sleepMinutes','activeCalories','totalCalories','restingHeartRate','averageHeartRate','stressAverage','hrvMs','latestActivity'].some(key=>parsed[key]!==undefined);if(!useful)throw new Error('Aucune métrique santé reconnue dans ce fichier.');const summary={...parsed,sourceFileName:file.name,sourceFormat:(file.name.split('.').pop()||file.type||'inconnu').toUpperCase(),importedAt:new Date().toISOString()};paintHealth(summary);saveHealthLocal(summary);healthStatus.textContent=`${file.name} importé${summary.observedOn?` · données du ${summary.observedOn}`:''}.`;await syncHealthWithSession(authSession);notice('Les cartes santé ont été mises à jour.');}catch(error){healthStatus.textContent=error.message||'Impossible de lire ce fichier Garmin.';notice('Import Garmin non terminé.');}finally{healthImportBusy=false;healthFile.value='';}});
      healthDemo.addEventListener('click',()=>{const summary={observedOn:new Date().toISOString().slice(0,10),steps:7842,stepGoal:10000,sleepMinutes:438,activeCalories:612,totalCalories:2350,restingHeartRate:54,averageHeartRate:72,stressAverage:28,hrvMs:49,latestActivity:{name:'Course du matin',type:'Running',durationMinutes:42,distanceKm:7.3},sourceFileName:'Données de démonstration',sourceFormat:'DÉMO',importedAt:new Date().toISOString()};paintHealth(summary);saveHealthLocal(summary);healthStatus.textContent='Démo locale chargée : elle ne remplace pas vos données synchronisées.';document.getElementById('healthPrivacy').textContent='Données de démonstration locales · non synchronisées.';notice('Démo Garmin chargée.');});
      healthReset.addEventListener('click',async()=>{paintHealth(null);saveHealthLocal(null);healthStatus.textContent='Données santé effacées sur cet appareil.';if(authSession?.user&&supabaseClient){const result=await supabaseClient.from('health_snapshots').delete().eq('user_id',authSession.user.id);if(result.error)healthStatus.textContent='Effacé localement, mais la suppression Supabase a échoué.';}document.getElementById('healthPrivacy').textContent=authSession?.user?'Connecté · aucune donnée santé enregistrée.':'Données locales tant que vous n’êtes pas connecté.';notice('Les données santé ont été retirées.');});
      try{const storedHealth=JSON.parse(localStorage.getItem(healthStorageKey)||'null');paintHealth(storedHealth);if(storedHealth)healthStatus.textContent=`Dernier import : ${storedHealth.sourceFileName||'Garmin'}${storedHealth.observedOn?` · ${storedHealth.observedOn}`:''}.`;}catch(error){paintHealth(null)}
